/* Estudos aprofundados de passagens-chave.
   b = índice do livro (0 = Gênesis ... 65 = Apocalipse), c = capítulo, v = [início, fim] */
window.ESTUDOS = [
{id:"criacao",titulo:"No princípio: a criação",b:0,c:1,v:[1,31],ref:"Gênesis 1:1–2:3",cat:"Antigo Testamento",
 tema:"Deus, sozinho e soberano, cria pela palavra um mundo bom e ordenado, e coroa a criação com o ser humano à sua imagem.",
 contexto:"Os povos vizinhos contavam que o mundo nasceu de guerras entre deuses: no Enuma Elish babilônico, Marduque cria o céu com o cadáver da deusa Tiamat. Gênesis 1 é sereno e polêmico ao mesmo tempo: não há luta, o sol e a lua (adorados como deuses) são apenas “luminares”, e o ser humano não é escravo dos deuses, mas imagem e representante do Criador.",
 notas:[
  {v:"1",t:"“No princípio” (bereshit) e “criou” (bara): só Deus é sujeito desse verbo. “Os céus e a terra” é uma expressão para “tudo”. O versículo resume o capítulo."},
  {v:"2",t:"Tohu vavohu: sem forma e vazia. Os dias 1–3 resolvem a falta de forma (separando), os dias 4–6 resolvem o vazio (preenchendo). O Espírito (ruach) “pairava” como ave sobre o ninho (mesmo verbo em Dt 32:11)."},
  {v:"3",t:"“Disse Deus”: dez vezes no capítulo. A palavra de Deus é eficaz (Sl 33:6, 9). João começa seu evangelho ecoando este versículo (Jo 1:1-5)."},
  {v:"14-16",t:"O texto evita os nomes “sol” e “lua” (shemesh e yareach eram também nomes de divindades) e diz apenas “luminares”. As estrelas, objeto de culto astrológico na Babilônia, aparecem quase de passagem: “e as estrelas”."},
  {v:"26",t:"“Façamos”: Pais da Igreja viram aqui um indício da Trindade; muitos exegetas modernos leem como plural deliberativo ou corte celeste. “Imagem” (tselem) remete às estátuas que reis colocavam para marcar seu domínio: o ser humano representa o governo de Deus."},
  {v:"27",t:"Três vezes o verbo bara num só verso: o ponto alto do capítulo. “Macho e fêmea”: os dois, igualmente, são imagem de Deus."},
  {v:"28",t:"Primeira bênção à humanidade: frutificar e governar. “Dominar” aqui é mordomia de um rei que serve, à luz de Gn 2:15 (cultivar e guardar)."},
  {v:"31",t:"“Muito bom” (tov me'od). A matéria não é má. No sétimo dia (2:1-3) Deus “descansa”: no Antigo Oriente, o deus descansava ao ocupar seu templo. O cosmo é o templo de Deus."}
 ],
 palavras:["bereshit","bara","elohim","tohu","ruach","tselem","adam","tov"],
 teologos:[["Agostinho","Em “O Sentido Literal do Gênesis” advertiu cristãos a não dizerem bobagens sobre a natureza em nome da Bíblia, para não desacreditar a fé diante dos que conhecem ciência."],["Calvino","Moisés escreveu para o povo simples e descreveu o mundo como aparece aos olhos (acomodação). Quem quer astronomia deve ir a outro lugar."],["John Walton","“O Mundo Perdido de Gênesis Um”: o capítulo descreve a inauguração do cosmo como templo, atribuindo funções, e não principalmente a origem material."],["Bonhoeffer","Em “Criação e Queda” (1933), destaca que só podemos falar do princípio a partir do meio, isto é, a partir de Cristo."]],
 cristo:"Cl 1:16 e Jo 1:3 dizem que tudo foi criado por meio de Cristo. Ele é a imagem perfeita de Deus (Cl 1:15) que restaura a imagem em nós (2Co 3:18). A nova criação começa na ressurreição, no “primeiro dia da semana” (Jo 20:1).",
 perguntas:["O que muda na sua visão de si mesmo saber que é imagem de Deus?","Como Gn 1 responde a idolatrias atuais (dinheiro, natureza, Estado)?","O que significa para você que Deus chamou a criação de “muito boa”?"]},
{id:"queda",titulo:"A queda",b:0,c:3,v:[1,24],ref:"Gênesis 3",cat:"Antigo Testamento",
 tema:"A desconfiança da bondade de Deus leva à desobediência, e esta traz vergonha, culpa, conflito e morte. Mas Deus busca o culpado e promete vitória.",
 contexto:"Depois do jardim perfeito de Gn 2, este capítulo explica por que o mundo que conhecemos está quebrado. O resto da Bíblia é a história de como Deus desfaz Gn 3.",
 notas:[
  {v:"1",t:"A serpente é “astuta” (arum), jogo de palavras com “nus” (arummim) em 2:25. Ela começa questionando a palavra de Deus: “É assim que Deus disse?”"},
  {v:"4-5",t:"A primeira mentira teológica: “certamente não morrereis” e “sereis como Deus”. O núcleo do pecado é querer definir o bem e o mal por conta própria."},
  {v:"6",t:"“Boa para comer, agradável aos olhos, desejável para dar entendimento”: compare 1Jo 2:16 (concupiscência da carne, dos olhos e soberba da vida). O homem estava “com ela” e calado."},
  {v:"7-8",t:"Os olhos se abrem, mas para a vergonha. Escondem-se do Deus que “andava no jardim”, como no tabernáculo (Lv 26:12)."},
  {v:"9",t:"“Onde estás?”: Deus não pede informação, chama ao arrependimento. É a primeira pergunta de Deus na Bíblia."},
  {v:"12-13",t:"Transferência de culpa: o homem culpa a mulher e Deus (“a mulher que me deste”); a mulher culpa a serpente."},
  {v:"15",t:"Protoevangelho: a descendência da mulher esmagará a cabeça da serpente, ferida no calcanhar. A Septuaginta usa um pronome masculino singular (autos), e os Pais leram aqui Cristo (Ireneu)."},
  {v:"21",t:"Deus faz vestes de peles: uma provisão de graça que, segundo muitos intérpretes, implica a morte de um animal para cobrir a vergonha."},
  {v:"22-24",t:"Expulsão e querubins guardando a árvore da vida. A árvore reaparece em Ap 22:2, acessível de novo."}
 ],
 palavras:["chattat","adam","yada","tov"],
 teologos:[["Agostinho","A raiz da queda foi a soberba, o amor de si até o desprezo de Deus (A Cidade de Deus XIV.28)."],["Ireneu","Cristo recapitula Adão: onde Adão desobedeceu junto a uma árvore, Cristo obedeceu sobre uma árvore (Contra as Heresias V)."],["Bonhoeffer","A pergunta da serpente é a primeira conversa “sobre” Deus em vez de “com” Deus: religião que se coloca acima da palavra."],["Kierkegaard","Em “O Conceito de Angústia” explora a liberdade e a angústia antes do pecado."]],
 cristo:"Paulo contrasta Adão e Cristo (Rm 5:12-21; 1Co 15:22). Jesus é tentado no deserto e vence onde Adão e Israel falharam (Mt 4:1-11). Na cruz Ele é ferido, mas esmaga a cabeça da serpente (Cl 2:15; Hb 2:14; Ap 12:9).",
 perguntas:["Em que áreas você duvida da bondade de Deus?","Como você costuma “se esconder” e “transferir culpa”?","Como a pergunta “Onde estás?” soa como graça?"]},
{id:"abraao",titulo:"Abraão creu: a aliança",b:0,c:15,v:[1,21],ref:"Gênesis 15",cat:"Antigo Testamento",
 tema:"Abraão é justificado pela fé, e Deus garante sozinho a aliança passando entre os animais.",
 contexto:"Abraão é velho e sem filhos. A promessa de Gn 12 parece impossível.",
 notas:[
  {v:"1",t:"“Não temas, Abrão; eu sou o teu escudo”: primeira vez em Gênesis que aparece “a palavra do SENHOR veio”, fórmula dos profetas."},
  {v:"5",t:"“Conta as estrelas”: a promessa é visual e absurda. A mesma noite que lhe mostra sua pequenez lhe mostra a grandeza de Deus."},
  {v:"6",t:"Texto-chave da Bíblia: “creu (he'emin, apoiou-se) no SENHOR, e isso lhe foi imputado como justiça”. Paulo o cita em Rm 4:3 e Gl 3:6; Tiago em Tg 2:23."},
  {v:"9-10",t:"Animais cortados ao meio: rito de aliança do Antigo Oriente. Quem passava entre as partes dizia: “que eu seja assim se quebrar o pacto” (Jr 34:18-20)."},
  {v:"12-16",t:"Profecia de 400 anos de escravidão: Deus vê a história adiante. “A medida da iniquidade dos amorreus ainda não está cheia” mostra paciência no juízo."},
  {v:"17",t:"Só um fogareiro e uma tocha (símbolos de Deus, como a coluna de fogo) passam entre os animais. Abraão dorme. Deus assume sozinho as consequências da aliança."}
 ],
 palavras:["aman","tsedaqah","berit"],
 teologos:[["Paulo (Rm 4)","Abraão foi justificado antes da circuncisão (Gn 17): logo é pai de todos os que creem, judeus e gentios."],["Lutero","Este versículo mostra que a fé que se apoia na promessa é contada como justiça diante de Deus (Preleções sobre Gênesis)."],["Meredith Kline","Comparou o rito ao juramento de autoimprecação em tratados antigos; aqui o próprio Deus se coloca sob a maldição."],["Kierkegaard","Em “Temor e Tremor” medita sobre a fé de Abraão (sobretudo Gn 22) como confiança no absurdo."]],
 cristo:"A descendência de Abraão é Cristo (Gl 3:16). Na cruz Deus de fato sofre a maldição da aliança quebrada (Gl 3:13). A fé que justifica Abraão é a mesma que justifica hoje (Rm 4:23-25).",
 perguntas:["Que promessa de Deus parece impossível para você hoje?","O que significa ser justificado “pela fé” em suas palavras?","O que nos consola no fato de Deus passar sozinho entre os animais?"]},
{id:"sarca",titulo:"A sarça ardente: EU SOU",b:1,c:3,v:[1,15],ref:"Êxodo 3:1-15",cat:"Antigo Testamento",
 tema:"Deus se revela pelo nome YHWH, ouve o clamor do povo e chama Moisés para libertá-lo.",
 contexto:"Moisés, aos 80 anos, é pastor fugitivo em Midiã. Israel geme no Egito.",
 notas:[
  {v:"2",t:"A sarça arde e não se consome: imagem de Deus presente sem destruir e, segundo muitos, de Israel que sofre sem ser aniquilado."},
  {v:"5",t:"“Tira as sandálias”: a santidade de Deus torna santo o lugar. Js 5:15 repete a cena."},
  {v:"6",t:"“Eu sou o Deus de Abraão, Isaque e Jacó”: Jesus usa este verso para provar a ressurreição, porque Deus não é Deus de mortos (Mc 12:26-27)."},
  {v:"7-8",t:"Quatro verbos de compaixão: vi, ouvi, conheço, desci. Deus não é indiferente ao sofrimento."},
  {v:"11-12",t:"“Quem sou eu?” Deus não responde quem Moisés é, mas quem estará com ele: “Eu serei contigo” (ehyeh imakh)."},
  {v:"14",t:"“EU SOU O QUE SOU” (ehyeh asher ehyeh): pode ser também “serei o que serei”. Indica a existência própria de Deus e sua fidelidade dinâmica. A Septuaginta traduz “Eu sou aquele que é” (ho ōn)."},
  {v:"15",t:"YHWH, “este é o meu nome eternamente”. Daqui vem o SENHOR em maiúsculas."}
 ],
 palavras:["yhwh","qadosh","yada","shema"],
 teologos:[["Tomás de Aquino","“Aquele que é” é o nome mais próprio de Deus: em Deus, ser e essência coincidem (Suma I, q.13, a.11)."],["Gregório de Nissa","Em “Vida de Moisés” lê a sarça como imagem da encarnação e da virgindade de Maria."],["Brevard Childs","O nome revela que Deus se dá a conhecer pela ação na história: Israel saberá quem Ele é pelo que fará."]],
 cristo:"Jesus diz: “antes que Abraão existisse, EU SOU” (Jo 8:58), e os soldados caem quando Ele diz “Eu sou” (Jo 18:6). Ele é o Deus que desceu para libertar (Fp 2:7).",
 perguntas:["Qual dos quatro verbos de Deus (ver, ouvir, conhecer, descer) mais o consola?","Quais são as suas desculpas como as de Moisés?","O que o nome “EU SOU” revela sobre a confiabilidade de Deus?"]},
{id:"decalogo",titulo:"Os Dez Mandamentos",b:1,c:20,v:[1,17],ref:"Êxodo 20:1-17",cat:"Antigo Testamento",
 tema:"Depois de libertar, Deus mostra ao seu povo como viver em liberdade, em amor a Ele e ao próximo.",
 contexto:"No Sinai, três meses depois do Egito. O hebraico os chama de “as dez palavras” (aseret hadevarim).",
 notas:[
  {v:"2",t:"O prefácio é graça: “Eu sou o SENHOR teu Deus, que te tirei do Egito”. A obediência é resposta, não meio de ganhar a salvação."},
  {v:"3-6",t:"Primeiro e segundo: só Deus e sem imagens. Católicos e luteranos (seguindo Agostinho) unem esses dois e dividem o décimo; reformados e ortodoxos os separam."},
  {v:"7",t:"Não “tomar” o nome em vão: literalmente “carregar” o nome. Inclui juramentos falsos e viver como povo de Deus de forma vazia."},
  {v:"8-11",t:"Sábado: dia de descanso também para servos, estrangeiros e animais. Em Dt 5:15 o motivo é a libertação do Egito."},
  {v:"12",t:"Honrar (kabbed, dar peso) pai e mãe: o primeiro mandamento com promessa (Ef 6:2)."},
  {v:"13-16",t:"Vida, casamento, propriedade e verdade. Jesus mostra que eles alcançam o coração: ira e desejo (Mt 5:21-30)."},
  {v:"17",t:"Não cobiçar: o único que trata do desejo interior. Foi este que convenceu Paulo do pecado (Rm 7:7)."}
 ],
 palavras:["torah","berit","yhwh","shabbat","qadosh"],
 teologos:[["Agostinho","Dividiu as dez palavras em duas tábuas: três sobre Deus e sete sobre o próximo."],["Lutero","No Catecismo Maior, explica cada mandamento com “devemos temer e amar a Deus” e mostra o lado positivo de cada proibição."],["Calvino","Três usos da lei: espelho que revela o pecado, freio que contém o mal e guia para o crente (Institutas II.7)."],["Tomás de Aquino","Os mandamentos expressam a lei natural, acessível à razão, agora revelada com clareza."]],
 cristo:"Jesus resume a Lei em amar a Deus e ao próximo (Mt 22:37-40) e cumpre a Lei perfeitamente (Mt 5:17). A nova aliança escreve a lei no coração (Jr 31:33; Hb 8:10).",
 perguntas:["Por que é importante que o v. 2 venha antes do v. 3?","Qual mandamento você acha mais difícil e por quê?","O que significa “carregar o nome de Deus em vão” hoje?"]},
{id:"shema",titulo:"Ouve, Israel",b:4,c:6,v:[1,25],ref:"Deuteronômio 6",cat:"Antigo Testamento",
 tema:"Amar o único Deus com todo o ser e transmitir essa fé à próxima geração no dia a dia.",
 contexto:"Moisés fala à nova geração antes de entrar na terra. Riqueza e conforto vão tentar o povo a esquecer Deus.",
 notas:[
  {v:"4",t:"Shemá Israel, YHWH Eloheinu, YHWH echad: “o SENHOR é nosso Deus, o SENHOR é um (ou: só o SENHOR)”. Echad indica unidade e exclusividade."},
  {v:"5",t:"Coração (lev: mente e vontade), alma (nefesh: a vida inteira) e força (me'od: “muito”, todos os recursos). Jesus acrescenta “entendimento” (Mc 12:30)."},
  {v:"6-9",t:"Palavras no coração, conversadas em casa, no caminho, ao deitar e levantar. Judeus usam filactérios (tefilin) e a mezuzá na porta para cumprir literalmente."},
  {v:"10-12",t:"Cidades que não edificaram, poços que não cavaram: o perigo da prosperidade é esquecer o Doador."},
  {v:"13,16",t:"Jesus cita estes versos contra Satanás no deserto (Mt 4:7,10)."},
  {v:"20-25",t:"Quando o filho perguntar, responda contando a história: “éramos escravos... e o SENHOR nos tirou”. A fé se transmite como narrativa vivida."}
 ],
 palavras:["shema","yhwh","ahavah","lev","nefesh"],
 teologos:[["Rabinos (Mishná)","O Shemá é recitado de manhã e à noite e eram as últimas palavras desejadas por um judeu fiel (Rabi Aquiba morreu dizendo “echad”)."],["Richard Bauckham","Em 1Co 8:6 Paulo reescreve o Shemá incluindo Jesus como o “um Senhor”, sem abandonar o monoteísmo."],["Agostinho","A ordem de amar a Deus “de todo” o coração não deixa parte da vida livre para outro amor que não seja nele."]],
 cristo:"Jesus chama este o primeiro e grande mandamento (Mt 22:37-38) e o cumpre perfeitamente. Em Cristo, Deus nos ama primeiro para que o amemos (1Jo 4:19).",
 perguntas:["Como a fé é transmitida na sua casa “no caminho”?","Que bênçãos podem levar você a esquecer Deus?","O que significa amar a Deus com a mente?"]},
{id:"sl23",titulo:"O SENHOR é meu pastor",b:18,c:23,v:[1,6],ref:"Salmo 23",cat:"Antigo Testamento",
 tema:"Confiança tranquila no cuidado de Deus em toda a jornada, inclusive na morte.",
 contexto:"Salmo de Davi, que foi pastor (1Sm 16:11; 17:34-35). No Antigo Oriente, reis eram chamados “pastores” do povo.",
 notas:[
  {v:"1",t:"“O SENHOR (YHWH) é meu pastor”: o nome da aliança e o pronome pessoal. “Nada me faltará” lembra o deserto: “nada te faltou” (Dt 2:7)."},
  {v:"2",t:"Pastos verdes e águas tranquilas (literalmente “águas de descanso”): ovelhas não bebem em águas agitadas."},
  {v:"3",t:"“Restaura a minha alma (nefesh)”: dá novo fôlego, faz voltar (shuv). “Caminhos da justiça”: trilhas certas, “por amor do seu nome”, isto é, por sua reputação."},
  {v:"4",t:"O pronome muda de “ele” para “tu” no vale escuro: no perigo, fala-se com Deus, não sobre Ele. A vara defende; o cajado guia e resgata."},
  {v:"5",t:"A imagem muda para anfitrião: mesa diante dos inimigos (hospitalidade que protege), unção com óleo (honra), cálice transbordante."},
  {v:"6",t:"Bondade e misericórdia (hesed) “me seguirão”: o verbo radaf significa perseguir. O amor leal de Deus corre atrás de nós."}
 ],
 palavras:["yhwh","nefesh","hesed","tov","shuv"],
 teologos:[["Agostinho","Nas “Exposições dos Salmos” lê o salmo como voz da Igreja guiada por Cristo e alimentada nos sacramentos."],["Spurgeon","Chamou-o de “a pérola dos Salmos” (O Tesouro de Davi)."],["Phillip Keller","Pastor de ovelhas, escreveu “Nada me Faltará”, explicando os costumes de pastoreio por trás de cada verso."]],
 cristo:"Jesus diz: “Eu sou o bom pastor; o bom pastor dá a vida pelas ovelhas” (Jo 10:11). Ele é o grande Pastor (Hb 13:20) e o Supremo Pastor (1Pe 5:4). No Apocalipse, o Cordeiro será o pastor (Ap 7:17).",
 perguntas:["Em que “vale escuro” você está ou já esteve?","O que significa ser perseguido pela misericórdia de Deus?","Que diferença faz dizer “meu” pastor?"]},
{id:"sl51",titulo:"Arrependimento: Salmo 51",b:18,c:51,v:[1,19],ref:"Salmo 51",cat:"Antigo Testamento",
 tema:"O pecador confessa o pecado sem desculpas e pede um coração novo, confiando na misericórdia de Deus.",
 contexto:"Segundo o título, Davi o compôs depois que Natã o confrontou pelo adultério com Bate-Seba e o assassinato de Urias (2Sm 11–12).",
 notas:[
  {v:"1-2",t:"Três palavras para o perdão (apaga, lava, purifica) e três para o pecado (transgressão, iniquidade, pecado). O pedido se baseia na hesed e no rachamim de Deus, não em mérito."},
  {v:"4",t:"“Contra ti, contra ti somente pequei”: Davi pecou contra pessoas, mas todo pecado é antes de tudo contra Deus. Paulo cita o verso em Rm 3:4."},
  {v:"5",t:"“Em pecado me concebeu minha mãe”: não condena a mãe nem o sexo, mas confessa que o pecado está na raiz do ser. Base bíblica do pecado original."},
  {v:"7",t:"Hissopo era usado para aspergir sangue na Páscoa (Êx 12:22) e na purificação de leprosos (Lv 14)."},
  {v:"10",t:"“Cria (bara) em mim um coração puro”: só Deus cria. O arrependimento verdadeiro pede uma nova criação."},
  {v:"11",t:"“Não retires de mim o teu Espírito Santo”: Davi viu o Espírito deixar Saul (1Sm 16:14)."},
  {v:"16-17",t:"Deus não quer sacrifício como ritual vazio, mas um “coração quebrantado e contrito”."}
 ],
 palavras:["hesed","rachamim","pesha","avon","chattat","bara","ruach","lev"],
 teologos:[["Agostinho","Pediu que os salmos penitenciais fossem escritos na parede junto ao seu leito de morte (Possídio, “Vida de Agostinho” 31)."],["Lutero","Comentou o Sl 51 dizendo que nele se aprende o conhecimento de Deus e do homem."],["Calvino","Viu neste salmo um modelo de verdadeiro arrependimento que não esconde nada."]],
 cristo:"Cristo é o sacrifício pelo qual Deus pode apagar pecados sem negar sua justiça (Rm 3:25-26). O Espírito agora habita permanentemente no crente (Jo 14:16; Ef 1:13).",
 perguntas:["Você confessa pecados com desculpas ou sem elas?","O que significa pedir um coração novo em vez de apenas perdão?","Como este salmo pode ser uma oração sua?"]},
{id:"is6",titulo:"Santo, santo, santo",b:22,c:6,v:[1,13],ref:"Isaías 6",cat:"Antigo Testamento",
 tema:"A visão da santidade de Deus leva à confissão, à purificação e ao envio.",
 contexto:"740 a.C., ano da morte do rei Uzias, que reinou 52 anos e morreu leproso por invadir o santuário (2Cr 26). O trono humano está vazio; o trono divino está ocupado.",
 notas:[
  {v:"1",t:"“Vi o Senhor (Adonai) assentado sobre um alto e sublime trono”: a orla do manto enche o Templo; Deus é grande demais para o edifício."},
  {v:"2",t:"Serafins (“seres ardentes”) cobrem o rosto (não podem olhar) e os pés (humildade), e com duas asas voam (servem)."},
  {v:"3",t:"“Santo, santo, santo”: a repetição tripla é superlativo hebraico. Só a santidade é elevada à terceira potência na Bíblia. A igreja cristã canta isso no Sanctus."},
  {v:"5",t:"“Ai de mim! Estou perdido”: diante do Santo, o profeta vê primeiro os próprios lábios impuros, justamente o instrumento do seu ministério."},
  {v:"6-7",t:"A brasa do altar (do sacrifício) toca os lábios: “a tua iniquidade foi tirada e o teu pecado perdoado (kipper)”."},
  {v:"8",t:"Só depois de purificado ele ouve o chamado e responde: “Eis-me aqui, envia-me a mim”."},
  {v:"9-10",t:"Missão dura: a pregação vai endurecer os ouvintes. Jesus cita para explicar as parábolas (Mt 13:14-15); Paulo, para a rejeição de Israel (At 28:26-27)."},
  {v:"13",t:"Mesmo cortada, a árvore deixa um toco: “a santa semente é o seu tronco”. Esperança do remanescente."}
 ],
 palavras:["qadosh","kavod","adonai","kipper","avon"],
 teologos:[["R. C. Sproul","“A Santidade de Deus” parte deste capítulo para mostrar que conhecer a santidade divina é traumático e restaurador."],["Rudolf Otto","O encontro de Isaías é exemplo clássico do mysterium tremendum et fascinans."],["Calvino","Quem não foi abalado pela majestade de Deus nunca se conheceu de verdade (Institutas I.1.3, citando Isaías)."]],
 cristo:"João diz que Isaías “viu a sua glória”, a de Jesus, e falou dele (Jo 12:41). A brasa do altar aponta para o sacrifício de Cristo, que purifica de verdade (Hb 9:14).",
 perguntas:["Por que a confissão vem antes do envio?","Que “trono vazio” na sua vida pode estar chamando você a olhar para o trono de Deus?","Como cantar “santo” muda o nosso culto?"]},
{id:"is53",titulo:"O Servo sofredor",b:22,c:53,v:[1,12],antes:[52,13,15],ref:"Isaías 52:13–53:12",cat:"Antigo Testamento",
 tema:"O Servo do SENHOR sofre rejeição e morte no lugar de muitos, leva seus pecados e é exaltado.",
 contexto:"Quarto Cântico do Servo. Escrito séculos antes de Jesus (o Grande Rolo de Isaías de Qumran, c. 125 a.C., já o contém). Comece a leitura em 52:13.",
 notas:[
  {v:"52:13-15",t:"Moldura: o Servo será exaltado, mas antes desfigurado. “Aspergirá muitas nações”: linguagem sacerdotal de purificação."},
  {v:"2-3",t:"Raiz em terra seca, sem aparência atraente, desprezado, “homem de dores, experimentado no sofrimento”."},
  {v:"4-6",t:"Coração do poema: “ele levou as nossas dores... foi traspassado pelas nossas transgressões... o castigo que nos traz a paz (shalom) estava sobre ele”. Pronomes: ele / nós, repetidos."},
  {v:"6",t:"“Todos nós andávamos desgarrados como ovelhas... mas o SENHOR fez cair sobre ele a iniquidade (avon) de nós todos”."},
  {v:"7",t:"Como cordeiro mudo ao matadouro. O eunuco etíope lia este verso quando Filipe o encontrou (At 8:32-35)."},
  {v:"9",t:"Sepultura com ímpios e com o rico: Jesus morreu entre criminosos e foi sepultado no túmulo de José de Arimateia, homem rico (Mt 27:57-60)."},
  {v:"10",t:"“Oferta pelo pecado” (asham, oferta de reparação): a morte do Servo é sacrifício. “Verá a sua posteridade e prolongará os seus dias”: vida depois da morte."},
  {v:"11-12",t:"“Pelo seu conhecimento, o meu servo justo justificará a muitos”. Intercede pelos transgressores, como Jesus na cruz (Lc 23:34)."}
 ],
 palavras:["eved","avon","pesha","shalom","tsedaqah","kipper"],
 teologos:[["Jerônimo","Disse que Isaías deveria ser chamado mais evangelista do que profeta."],["Agostinho","Cita Is 53 para mostrar que os judeus da diáspora, guardando as Escrituras, são testemunhas involuntárias de Cristo."],["J. Alec Motyer","Mostra que o poema tem cinco estrofes simétricas, com a substituição (vv. 4-6) no centro."],["Tradição judaica","Muitos intérpretes judeus medievais (Rashi) leram o Servo como Israel; alguns textos rabínicos antigos o leram como o Messias."]],
 cristo:"É o capítulo do AT mais aplicado à paixão: Mt 8:17; Lc 22:37; Jo 12:38; At 8:32-35; Rm 10:16; 1Pe 2:22-25. Jesus disse ter vindo “dar a sua vida em resgate de muitos” (Mc 10:45), ecoando o v. 12.",
 perguntas:["Leia os vv. 4-6 trocando “nós” pelo seu nome. O que sente?","Por que o silêncio do Servo é importante?","Como este texto fala a quem é desprezado?"]},
{id:"novaalianca",titulo:"A Nova Aliança",b:23,c:31,v:[31,34],ref:"Jeremias 31:31-34",cat:"Antigo Testamento",
 tema:"Deus promete uma aliança nova, em que a lei é escrita no coração, todos o conhecem e os pecados são perdoados para sempre.",
 contexto:"No meio das ruínas de Jerusalém, Jeremias recebe o “Livro da Consolação” (cap. 30–33).",
 notas:[
  {v:"31",t:"“Farei uma aliança nova”: é a única ocorrência da expressão no AT. Com Israel e Judá juntos."},
  {v:"32",t:"Diferente da aliança do Sinai, que o povo quebrou, “embora eu fosse seu marido”. A falha não estava na lei, mas no coração."},
  {v:"33",t:"“Porei a minha lei (torah) no seu interior e a escreverei no seu coração (lev)”: a lei é a mesma, o lugar é novo. Ez 36:26-27 acrescenta: “porei dentro de vós o meu Espírito”."},
  {v:"34",t:"Todos me conhecerão (yada), “do menor ao maior”: não haverá elite espiritual. A base é o perdão: “me esquecerei dos seus pecados”."}
 ],
 palavras:["berit","torah","lev","yada","avon","chattat"],
 teologos:[["Agostinho","Em “O Espírito e a Letra”, mostra que na nova aliança a lei não muda, mas o Espírito dá amor para cumpri-la."],["Calvino","Destacou a continuidade: a substância das alianças é a mesma (Cristo); muda a clareza e a forma da administração."],["Batistas e dispensacionalistas","Destacam a novidade: todos os membros da nova aliança conhecem a Deus, o que influencia sua visão do batismo."]],
 cristo:"Na Ceia, Jesus disse: “Este cálice é a nova aliança no meu sangue” (Lc 22:20). Hebreus cita o texto inteiro (Hb 8:8-12) e mostra Cristo como mediador da nova aliança.",
 perguntas:["Qual a diferença entre obedecer por obrigação e por ter a lei no coração?","Que consolo há em Deus “esquecer” pecados?","Como a Ceia nos lembra desta promessa?"]},
{id:"bemaventurancas",titulo:"As Bem-aventuranças",b:39,c:5,v:[1,16],ref:"Mateus 5:1-16",cat:"Novo Testamento",
 tema:"Jesus descreve o caráter dos cidadãos do Reino e declara felizes aqueles que o mundo considera derrotados.",
 contexto:"Início do Sermão do Monte (Mt 5–7). Jesus sobe ao monte e se senta, postura de mestre, como novo Moisés que interpreta a Lei.",
 notas:[
  {v:"3",t:"“Bem-aventurados (makarioi) os pobres de espírito”: os que reconhecem a falência espiritual. Lucas diz apenas “pobres” (Lc 6:20). A primeira e a oitava promessa são iguais: “deles é o Reino”, uma moldura."},
  {v:"4",t:"Os que choram: pelo pecado e pelo mal no mundo. Ecoa Is 61:2-3."},
  {v:"5",t:"Os mansos (praeis) herdarão a terra: citação do Sl 37:11. Mansidão é força sob controle."},
  {v:"6",t:"Fome e sede de justiça (dikaiosynē): tanto justiça pessoal quanto justiça no mundo."},
  {v:"7-9",t:"Misericordiosos, puros de coração (integridade sem duplicidade) e pacificadores (que fazem shalom). Estes “verão a Deus” e “serão chamados filhos de Deus”."},
  {v:"10-12",t:"Perseguidos “por causa de mim”: Jesus se coloca no lugar que só Deus ocupava nas promessas dos profetas."},
  {v:"13-16",t:"Sal (preserva e dá sabor) e luz (mostra o caminho). Não são ordens para se tornar; são identidade: “vós sois”."}
 ],
 palavras:["makarios","basileia","praus","dikaiosyne","eirene","shalom"],
 teologos:[["Agostinho","Viu nas bem-aventuranças sete degraus (a oitava retoma a primeira) ligados aos sete dons do Espírito de Is 11."],["Lutero","O Sermão do Monte não é só para monges, mas para todo cristão em sua vocação diária."],["Bonhoeffer","“Discipulado”: o Sermão descreve a vida concreta de quem segue Jesus; separá-lo da vida é graça barata."],["Lloyd-Jones","“Estudos no Sermão do Monte”: as bem-aventuranças descrevem o caráter cristão, e todas devem estar presentes em todo crente."],["John Stott","Chamou o Sermão de “contracultura cristã”."]],
 cristo:"Jesus é o exemplo perfeito de cada bem-aventurança: pobre, que chorou, manso, justo, misericordioso, puro, pacificador, perseguido. Não é só um código: é um retrato dele.",
 perguntas:["Qual bem-aventurança contradiz mais os valores de hoje?","Por que o reconhecimento da pobreza espiritual vem primeiro?","Onde você está sendo sal e luz nesta semana?"]},
{id:"prodigo",titulo:"O pai que corre: Lucas 15",b:41,c:15,v:[1,32],ref:"Lucas 15",cat:"Novo Testamento",
 tema:"Três parábolas sobre a alegria de Deus ao encontrar o perdido e o perigo do irmão mais velho.",
 contexto:"Os fariseus murmuravam porque Jesus recebia pecadores e comia com eles (v. 1-2). As parábolas respondem a essa crítica.",
 notas:[
  {v:"1-2",t:"O público é duplo: pecadores (como o filho mais novo) e fariseus (como o mais velho). A história termina olhando para os críticos."},
  {v:"4-10",t:"Ovelha (1 em 100), moeda (1 em 10), filho (1 em 2): a proporção vai aumentando. Em todas há busca, achado e festa."},
  {v:"12",t:"Pedir a herança em vida era como desejar a morte do pai. O pai concede: Deus respeita a liberdade."},
  {v:"15-16",t:"Cuidar de porcos era a degradação máxima para um judeu."},
  {v:"17",t:"“Caindo em si”: o arrependimento começa como lucidez. Mas seu discurso ainda é de negociação (“trata-me como um dos teus empregados”)."},
  {v:"20",t:"O pai o vê de longe (estava esperando), sente compaixão (esplanchnisthē), corre (algo humilhante para um patriarca no Oriente), abraça e beija antes de ouvir a confissão."},
  {v:"22-24",t:"Melhor roupa, anel (autoridade), sandálias (filho, não escravo), banquete. “Estava morto e reviveu”."},
  {v:"25-32",t:"O mais velho também está longe, mesmo em casa: obedeceu como escravo (“há tantos anos te sirvo”). O pai sai para buscá-lo também. A história termina sem resposta: cabe aos ouvintes."}
 ],
 palavras:["splanchnizomai","metanoia","charis","hamartia"],
 teologos:[["Timothy Keller","“O Deus Pródigo”: “pródigo” significa esbanjador; o pai é pródigo em graça. Há duas formas de fugir de Deus: quebrando as regras ou cumprindo-as para controlá-lo."],["Kenneth Bailey","Explicou os costumes do Oriente Médio por trás da parábola em “A Poesia e o Camponês” e “O Deus Pródigo”."],["Henri Nouwen","“A Volta do Filho Pródigo”, meditação sobre o quadro de Rembrandt: somos chamados a nos tornar o pai."],["Rembrandt","Pintou “O Retorno do Filho Pródigo” (c. 1669), um dos quadros mais famosos de tema bíblico."]],
 cristo:"Jesus é quem conta a história e a encarna: Ele é o pastor que busca (Lc 19:10), e é o verdadeiro Irmão mais velho que deixa a casa do Pai para nos buscar (Keller).",
 perguntas:["Você se identifica mais com o filho mais novo ou o mais velho?","O que significa o pai correr?","Como você recebe os que “voltam” à igreja?"]},
{id:"prologo",titulo:"A Palavra se fez carne",b:42,c:1,v:[1,18],ref:"João 1:1-18",cat:"Novo Testamento",
 tema:"A Palavra eterna, que é Deus, criou tudo e se fez homem para revelar o Pai e dar aos que creem o direito de serem filhos de Deus.",
 contexto:"O prólogo de João é como a abertura de uma ópera: apresenta os temas do evangelho (vida, luz, testemunho, fé, glória, graça e verdade).",
 notas:[
  {v:"1",t:"Três afirmações: a Palavra (logos) já existia no princípio (eternidade), estava com Deus (pros ton theon: distinção e relação face a face) e era Deus (theos ēn ho logos: divindade)."},
  {v:"3",t:"“Todas as coisas foram feitas por meio dela”: a Palavra não é criatura, é Criador."},
  {v:"4-5",t:"Vida e luz. “As trevas não a compreenderam”: o verbo katalambanō pode significar entender ou vencer. As duas leituras são possíveis."},
  {v:"11",t:"“Veio para o que era seu, e os seus não o receberam”: resumo trágico da primeira metade do evangelho."},
  {v:"12-13",t:"Aos que creem, dá “autoridade” (exousia) de se tornarem filhos de Deus, nascidos de Deus, não de vontade humana."},
  {v:"14",t:"O versículo central: a Palavra “se fez carne” (sarx, condição humana frágil) e “habitou” (eskēnōsen, armou tenda) entre nós. “Vimos a sua glória (doxa)”: como a glória no tabernáculo. “Cheio de graça e de verdade” ecoa o hesed e emet de Êx 34:6."},
  {v:"17",t:"A lei veio por Moisés (dom); a graça e a verdade vieram por Jesus Cristo (dom pleno)."},
  {v:"18",t:"“Ninguém jamais viu a Deus; o Deus unigênito (melhores manuscritos: monogenēs theos), que está no seio do Pai, esse o revelou (exēgēsato, de onde vem “exegese”)”. Jesus é a exegese de Deus."}
 ],
 palavras:["logos","skenoo","doxa","charis","aletheia","monogenes","sarx","exousia","kosmos"],
 teologos:[["Agostinho","Disse ter lido nos livros dos platônicos que no princípio era o Verbo, mas não que o Verbo se fez carne (Confissões VII.9)."],["Atanásio","O Verbo assumiu um corpo para que a morte fosse vencida nele e a imagem de Deus fosse renovada (A Encarnação do Verbo)."],["Calvino","Comentou que o v. 14 é o centro do evangelho: Deus se revestiu de nossa carne."],["Raymond Brown","Sugere que o prólogo foi um hino cristão primitivo adaptado por João."]],
 cristo:"O texto é inteiro sobre Cristo. Ele é a Palavra criadora de Gn 1, a glória do tabernáculo, a Sabedoria de Pv 8 e o revelador do Pai.",
 perguntas:["Por que importa que a Palavra se fez “carne” e não apenas pareceu humana?","O que significa “receber” a Cristo?","Que diferença faz Jesus ser a “exegese” de Deus?"]},
{id:"nicodemos",titulo:"Nascer de novo",b:42,c:3,v:[1,21],ref:"João 3:1-21",cat:"Novo Testamento",
 tema:"Ninguém entra no Reino de Deus sem nascer do alto pelo Espírito, e esse novo nascimento vem por crer no Filho que Deus deu.",
 contexto:"Nicodemos é fariseu, membro do Sinédrio e “mestre de Israel”. Vem de noite, que em João também tem sentido simbólico.",
 notas:[
  {v:"2",t:"Nicodemos começa com elogio: “sabemos que és mestre vindo de Deus”. Jesus vai além: ele não precisa de um mestre, precisa de um novo nascimento."},
  {v:"3",t:"Anōthen: “de novo” e “do alto”. Nicodemos entende só o primeiro sentido (v. 4)."},
  {v:"5",t:"“Água e Espírito”: provável alusão a Ez 36:25-27 (água purificadora e Espírito novo), texto que um mestre de Israel deveria conhecer (v. 10). Outros veem referência ao batismo."},
  {v:"8",t:"Vento e Espírito são a mesma palavra (pneuma). Não se controla o vento, mas vê-se o efeito."},
  {v:"14-15",t:"A serpente de bronze (Nm 21): olhar para o objeto levantado trazia cura. “Levantado” em João indica cruz e exaltação ao mesmo tempo."},
  {v:"16",t:"“Deus amou o mundo (kosmos) de tal maneira”: o grego houtōs indica mais “deste modo” do que “tanto”. O modo do amor é o dom do Filho unigênito (monogenēs)."},
  {v:"17-18",t:"Jesus não veio para condenar. Quem não crê “já está condenado”: o juízo já está em curso na resposta a Jesus."},
  {v:"19-21",t:"Luz e trevas: as pessoas fogem da luz para não terem suas obras expostas. Nicodemos aparece depois mais corajoso (7:50; 19:39)."}
 ],
 palavras:["anothen","pneuma","basileia","agape","kosmos","monogenes","zoe","pistis"],
 teologos:[["Agostinho","Pregou que Nicodemos conhecia só um nascimento, de Adão para a morte; Jesus anuncia outro, de Deus para a vida (Tratados sobre João 11-12)."],["Lutero","Chamou Jo 3:16 de “o evangelho em miniatura” (frase popularmente atribuída a ele)."],["Wesley","Seu sermão “O Novo Nascimento” (1760) define-o como a grande mudança que Deus opera na alma quando a traz à vida."],["D. A. Carson","Defende a leitura de Ez 36 como chave para “água e Espírito”."]],
 cristo:"O Filho do Homem desceu do céu e será levantado na cruz. Olhar para Ele com fé traz vida, como na serpente de bronze.",
 perguntas:["Em que você se parece com Nicodemos?","O que o vento ensina sobre a obra do Espírito?","Explique Jo 3:16 com suas palavras a alguém que nunca leu."]},
{id:"rm3",titulo:"Justificados gratuitamente",b:44,c:3,v:[21,31],ref:"Romanos 3:21-31",cat:"Novo Testamento",
 tema:"A justiça de Deus foi revelada em Cristo: todos pecaram, e todos que creem são justificados gratuitamente pela graça, por meio da redenção na cruz.",
 contexto:"De 1:18 a 3:20, Paulo mostrou que gentios e judeus estão todos debaixo do pecado. “Mas agora” (3:21) é a virada do livro.",
 notas:[
  {v:"21",t:"“Mas agora”: a história mudou. A justiça de Deus se manifestou “sem a lei”, mas testemunhada pela Lei e pelos Profetas: não é ideia nova, é cumprimento."},
  {v:"22-23",t:"Pela fé em Jesus Cristo (ou “fidelidade de Jesus Cristo”, debate de pistis Christou) para todos. “Não há distinção, pois todos pecaram e carecem da glória de Deus”: o problema é universal e a solução também."},
  {v:"24",t:"Três palavras-chave: justificados (dikaioumenoi, declarados justos), gratuitamente (dōrean, como presente; usado em Jo 15:25 para “sem motivo”) e redenção (apolytrōsis, libertação por resgate)."},
  {v:"25",t:"Hilastērion: propiciação ou propiciatório (a tampa da arca). Cristo é o lugar onde Deus se encontra com o pecador e onde o pecado é tratado. A Bíblia Livre traduz “sacrifício de reconciliação”."},
  {v:"26",t:"Deus é “justo e justificador”: a cruz resolve o dilema de como Deus pode perdoar sem tratar o mal como se não fosse nada."},
  {v:"27-28",t:"Não há lugar para orgulho. “O homem é justificado pela fé sem as obras da lei”. Lutero traduziu “somente pela fé” (allein), acrescentando “somente” para expressar o sentido."},
  {v:"29-31",t:"Deus é Deus de judeus e gentios (o Shemá: “Deus é um só”). A fé não anula a lei, antes a confirma."}
 ],
 palavras:["dikaiosyne","dikaioo","charis","apolytrosis","hilasterion","pistis","hamartia","doxa","nomos"],
 teologos:[["Lutero","Chamou Rm 3:23-26 de “o ponto principal e o lugar central da epístola e de toda a Bíblia” (nota marginal em sua Bíblia)."],["Calvino","Não há passagem em toda a Escritura que ilustre melhor a justiça de Deus em Cristo (Comentário a Romanos)."],["Leon Morris","Defendeu o sentido de propiciação em “A Pregação Apostólica da Cruz”."],["N. T. Wright","Lê a passagem dentro do tema da fidelidade de Deus à aliança com Abraão, que inclui os gentios."],["Douglas Moo","Comentário que equilibra as leituras tradicional e da Nova Perspectiva."]],
 cristo:"Cristo é o lugar da propiciação, o redentor e a prova pública de que Deus é justo e misericordioso ao mesmo tempo.",
 perguntas:["Por que “não há distinção” é boa e má notícia ao mesmo tempo?","O que significa receber a justiça como presente?","Como a justificação acaba com o orgulho religioso?"]},
{id:"rm8",titulo:"Nenhuma condenação: Romanos 8",b:44,c:8,v:[1,39],ref:"Romanos 8",cat:"Novo Testamento",
 tema:"Em Cristo não há condenação; o Espírito dá vida, adoção e esperança, e nada pode separar os crentes do amor de Deus.",
 contexto:"Depois da luta com o pecado em Rm 7, Paulo chega ao ápice da carta. O Espírito, mencionado poucas vezes até aqui, aparece cerca de 20 vezes neste capítulo.",
 notas:[
  {v:"1",t:"“Nenhuma condenação há para os que estão em Cristo Jesus”: veredicto definitivo. Começa com “nenhuma condenação” e termina com “nenhuma separação” (v. 39)."},
  {v:"3",t:"O que a lei não podia fazer, Deus fez enviando seu Filho “em semelhança de carne de pecado”, e “condenou o pecado na carne”. O pecado foi condenado, não o pecador."},
  {v:"5-9",t:"Carne (sarx) e Espírito: dois modos de existir. Não é corpo contra alma; é a vida centrada em si contra a vida conduzida por Deus."},
  {v:"15",t:"Espírito de adoção: clamamos “Aba, Pai”. Aba é a palavra aramaica de intimidade familiar que Jesus usou no Getsêmani (Mc 14:36)."},
  {v:"17",t:"Herdeiros de Deus e coerdeiros com Cristo, “se com ele sofremos”: o caminho para a glória passa pelo sofrimento."},
  {v:"18-25",t:"A criação geme como em dores de parto, esperando a redenção dos filhos de Deus. A salvação é cósmica e inclui o corpo."},
  {v:"26-27",t:"O Espírito intercede com gemidos inexprimíveis: até na oração fraca não estamos sós."},
  {v:"28-30",t:"Todas as coisas cooperam para o bem dos que amam a Deus. A “corrente de ouro”: conheceu, predestinou, chamou, justificou, glorificou (no passado, tão certo é)."},
  {v:"31-39",t:"Cinco perguntas sem resposta possível contra nós. A lista final cobre tempo, espaço e poderes espirituais: nada separa do amor de Deus em Cristo."}
 ],
 palavras:["pneuma","sarx","doxa","elpis","agape","dikaioo","hypomone"],
 teologos:[["Lutero","Rm 8:28 mostra que até o sofrimento é instrumento do amor de Deus para o cristão."],["Calvino","Usou os vv. 29-30 na doutrina da eleição; a certeza da salvação depende da fidelidade de Deus."],["Wesley","Leu a presciência (v. 29) como Deus conhecendo antecipadamente quem creria."],["Martyn Lloyd-Jones","Pregou quatro volumes só sobre Romanos 8."],["John Stott","Chamou Rm 8 de “o capítulo do Espírito”."]],
 cristo:"Cristo morreu, ressuscitou, está à direita de Deus e intercede por nós (v. 34). O amor de Deus é inseparável dele: é “o amor de Deus que está em Cristo Jesus”.",
 perguntas:["O que muda viver sabendo que não há condenação?","Como o v. 28 se aplica (e não se aplica) a um sofrimento seu?","Que “nada” da lista final mais ameaça você?"]},
{id:"amor",titulo:"O caminho do amor",b:45,c:13,v:[1,13],ref:"1 Coríntios 13",cat:"Novo Testamento",
 tema:"Sem amor, até os maiores dons são nada; o amor é paciente, bondoso e eterno.",
 contexto:"Paulo está no meio da discussão sobre dons espirituais (cap. 12–14). Os coríntios competiam por dons espetaculares. O capítulo não foi escrito para casamentos, mas para uma igreja dividida.",
 notas:[
  {v:"1-3",t:"Línguas, profecia, conhecimento, fé, generosidade, até martírio: sem amor, “nada sou” e “nada me aproveita”. O “sino que retine” alude talvez aos gongos de cultos pagãos de Corinto."},
  {v:"4-7",t:"Quinze verbos: o amor faz e não faz. Muitos são o oposto do que Paulo criticou nos coríntios: inveja (3:3), arrogância (4:18; 5:2), buscar os próprios interesses (10:24)."},
  {v:"5",t:"“Não guarda rancor”: literalmente “não registra o mal” (logizetai), verbo de contabilidade, o mesmo usado para Deus não “imputar” pecados (Rm 4:8)."},
  {v:"8-10",t:"Profecias, línguas e conhecimento passarão “quando vier o que é perfeito” (to teleion). A maioria entende a volta de Cristo; alguns cessacionistas entendem o cânon completo."},
  {v:"12",t:"Espelho “em enigma”: Corinto produzia espelhos de bronze, que davam imagem imperfeita. Depois veremos “face a face”."},
  {v:"13",t:"Fé, esperança e amor permanecem; o maior é o amor, porque a fé virará vista e a esperança, posse, mas o amor nunca acaba."}
 ],
 palavras:["agape","charisma","teleios","elpis","pistis"],
 teologos:[["Agostinho","Toda Escritura existe para formar amor a Deus e ao próximo; quem pensa entender a Bíblia sem edificar esse amor ainda não a entendeu (A Doutrina Cristã I.36)."],["Jonathan Edwards","“Caridade e seus Frutos” (1738) são 16 sermões sobre este capítulo."],["Anders Nygren","Usou este capítulo como retrato do ágape, amor que se doa."],["Gordon Fee","Lembra que o capítulo é corretivo para uma igreja orgulhosa dos dons."]],
 cristo:"Coloque “Jesus” no lugar de “amor” nos vv. 4-7 e o texto faz sentido perfeito. Ponha seu nome e verá o quanto precisa da graça.",
 perguntas:["Qual dos 15 verbos você mais precisa praticar?","Como o amor muda o uso de dons na igreja?","O que significa “não registrar o mal” num conflito atual?"]},
{id:"ressurreicao",titulo:"Se Cristo não ressuscitou",b:45,c:15,v:[1,58],ref:"1 Coríntios 15",cat:"Novo Testamento",
 tema:"A ressurreição de Cristo é histórica e central; ela garante a ressurreição corporal dos crentes e a vitória sobre a morte.",
 contexto:"Alguns em Corinto, influenciados pela visão grega que desprezava o corpo, negavam a ressurreição dos mortos (v. 12).",
 notas:[
  {v:"3-5",t:"Credo antigo que Paulo “recebeu”: morreu pelos pecados, foi sepultado, ressuscitou ao terceiro dia, apareceu. Muitos estudiosos datam este credo a poucos anos da crucificação."},
  {v:"6",t:"Apareceu a mais de 500 irmãos de uma vez, “dos quais a maior parte vive ainda”: convite a conferir."},
  {v:"14-19",t:"Se Cristo não ressuscitou, a pregação é vazia, a fé é inútil, ainda estamos em pecado e somos os mais dignos de pena. Paulo não oferece uma fé que funcione sem o fato."},
  {v:"20",t:"“Mas, de fato, Cristo ressuscitou”: primícias, o primeiro feixe da colheita que garante o restante."},
  {v:"21-22",t:"Adão e Cristo: em Adão todos morrem, em Cristo todos serão vivificados."},
  {v:"35-44",t:"Analogia da semente: o corpo semeado em fraqueza ressuscita em poder. “Corpo espiritual” (sōma pneumatikon) não é corpo feito de espírito, mas corpo totalmente animado pelo Espírito."},
  {v:"51-55",t:"“Num abrir e fechar de olhos”. “Onde está, ó morte, a tua vitória?” cita Os 13:14."},
  {v:"58",t:"Conclusão prática: “Portanto, sede firmes... o vosso trabalho não é vão no Senhor”. A esperança futura dá valor ao trabalho presente."}
 ],
 palavras:["anastasis","soma","euangelion","hamartia","sarx","pneuma"],
 teologos:[["Atanásio","A coragem dos cristãos diante da morte prova que ela foi vencida (A Encarnação do Verbo 27)."],["N. T. Wright","“A Ressurreição do Filho de Deus” analisa este capítulo e mostra que a ressurreição sempre significou corpo, não espírito."],["Karl Barth","Escreveu “A Ressurreição dos Mortos” (1924), uma exposição deste capítulo como chave de toda a carta."],["Gary Habermas","Usa o credo dos vv. 3-7 como evidência histórica primitiva."]],
 cristo:"Cristo é as primícias, o último Adão, o espírito vivificante. A vitória dele sobre a morte é a nossa.",
 perguntas:["Por que Paulo diz que sem a ressurreição a fé é inútil?","Como a esperança da ressurreição muda o luto?","O que torna seu trabalho “não vão no Senhor”?"]},
{id:"ef2",titulo:"Salvos pela graça",b:48,c:2,v:[1,22],ref:"Efésios 2",cat:"Novo Testamento",
 tema:"Estávamos mortos, Deus nos deu vida pela graça mediante a fé, e em Cristo une judeus e gentios num só povo e templo.",
 contexto:"Ef 1 descreveu as bênçãos em Cristo. O cap. 2 mostra de onde viemos e o que Deus fez.",
 notas:[
  {v:"1-3",t:"Diagnóstico: mortos em delitos e pecados, seguindo o mundo, o diabo e a carne. “Por natureza, filhos da ira”. Mortos não se ajudam."},
  {v:"4",t:"“Mas Deus”: duas palavras que mudam tudo. Rico em misericórdia, por causa do grande amor."},
  {v:"5-6",t:"Três verbos com o prefixo syn- (“junto com”): vivificou-nos juntamente com Cristo, ressuscitou-nos juntamente, fez-nos assentar juntamente nos lugares celestiais. União com Cristo."},
  {v:"8",t:"“Pela graça sois salvos, mediante a fé; e isto não vem de vós, é dom de Deus”. O pronome “isto” (touto, neutro) provavelmente se refere a todo o processo de salvação."},
  {v:"10",t:"Somos “feitura” dele (poiēma, de onde vem “poema”), criados em Cristo para boas obras. As obras não causam a salvação, mas são seu propósito."},
  {v:"11-13",t:"Os gentios estavam “sem Cristo, sem esperança e sem Deus no mundo”. Agora, “pelo sangue de Cristo, chegastes perto”."},
  {v:"14",t:"“Ele é a nossa paz” e derrubou a parede de separação. No Templo havia de fato um muro que proibia gentios de entrar, sob pena de morte (inscrições encontradas em 1871 e 1935)."},
  {v:"19-22",t:"Concidadãos, família de Deus, templo santo: a Igreja é o novo templo, com Cristo como pedra angular."}
 ],
 palavras:["charis","pistis","soteria","eirene","hamartia","sarx","ekklesia"],
 teologos:[["Agostinho","Usou Ef 2:8-9 contra os pelagianos: até a fé é dom de Deus."],["Lutero","Ef 2:8-10 ensina a ordem: primeiro a fé recebe a graça, depois vêm as obras como frutos."],["Martyn Lloyd-Jones","Pregou dois volumes de sermões só sobre Ef 2, destacando o “Mas Deus”."],["John Stott","Mostrou que os vv. 1-10 tratam da reconciliação com Deus e os vv. 11-22 da reconciliação entre pessoas: ambas são parte do evangelho."]],
 cristo:"Tudo acontece “em Cristo” e “com Cristo”: vida, ressurreição, assento celestial, paz, acesso ao Pai.",
 perguntas:["Como era sua vida antes do “Mas Deus”?","Que boas obras Deus preparou para você nesta fase?","Que muros a cruz precisa derrubar na sua igreja?"]},
{id:"fp2",titulo:"A mente de Cristo",b:49,c:2,v:[1,11],ref:"Filipenses 2:1-11",cat:"Novo Testamento",
 tema:"Cristo, sendo Deus, esvaziou-se, tornou-se servo e morreu na cruz; por isso Deus o exaltou. Os cristãos devem ter a mesma atitude.",
 contexto:"A igreja de Filipos enfrentava rivalidades (4:2). Paulo usa um provável hino cristão antigo como modelo de humildade.",
 notas:[
  {v:"3-4",t:"Nada por rivalidade ou vanglória. “Considerar os outros superiores” não é baixa autoestima, mas atenção ao interesse do outro."},
  {v:"6",t:"“Subsistindo em forma (morphē) de Deus”: forma que expressa a natureza real. “Não julgou como usurpação (harpagmon) o ser igual a Deus”: não considerou a igualdade algo a explorar em benefício próprio."},
  {v:"7",t:"“Esvaziou-se” (ekenōsen): não perdeu a divindade, mas a expressou de modo humilde, “tomando a forma de servo”. Esvaziou-se por adição (assumindo a humanidade), não por subtração."},
  {v:"8",t:"Humilhou-se até a morte, “e morte de cruz”: a forma mais vergonhosa de execução romana, reservada a escravos e rebeldes. Filipos, colônia romana, sabia o que isso significava."},
  {v:"9",t:"“Por isso Deus o exaltou soberanamente e lhe deu o nome que está acima de todo nome”: o nome é Senhor (kyrios), o nome de Deus."},
  {v:"10-11",t:"Todo joelho se dobrará: citação de Is 45:23, onde só YHWH recebe essa adoração. Paulo aplica a Jesus, para glória de Deus Pai."}
 ],
 palavras:["kenoo","kyrios","doxa","eved"],
 teologos:[["Atanásio","Usou este texto contra Ário: Aquele que estava em forma de Deus é igual ao Pai."],["Calvino","A forma de Deus é sua majestade; Ele a ocultou sob a carne, sem deixar de ser Deus."],["Gottfried Thomasius","Desenvolveu a teologia kenótica (séc. XIX), dizendo que o Filho abriu mão de atributos como a onisciência. Muitos a criticam."],["N. T. Wright","Mostra que o hino lê a cruz como revelação de quem Deus é, e não como algo contrário à divindade."],["Richard Bauckham","Destaca o uso de Is 45:23 como inclusão de Jesus na identidade de YHWH."]],
 cristo:"O texto é o retrato da encarnação, da cruz e da exaltação de Cristo, e é modelo ético para a Igreja.",
 perguntas:["Onde você está tentando “se agarrar” a direitos?","Que relação há entre doutrina (vv. 6-11) e vida em comunidade (vv. 1-5)?","O que significa “esvaziar-se” no seu trabalho ou família?"]},
{id:"hb11",titulo:"A galeria da fé",b:57,c:11,v:[1,40],ref:"Hebreus 11",cat:"Novo Testamento",
 tema:"A fé confia nas promessas invisíveis de Deus e age; os heróis do AT viveram e morreram pela fé, esperando algo melhor que se cumpre em Cristo.",
 contexto:"Os leitores, cristãos judeus perseguidos, estavam tentados a desistir (10:32-39). O autor mostra uma “nuvem de testemunhas” que perseverou.",
 notas:[
  {v:"1",t:"Fé é a “certeza” (hypostasis, realidade, fundamento, título de propriedade nos papiros) do que se espera e a convicção do que não se vê."},
  {v:"3",t:"Pela fé entendemos que o universo foi formado pela palavra de Deus: a criação é o primeiro artigo da fé."},
  {v:"6",t:"Sem fé é impossível agradar a Deus: é preciso crer que Ele existe e que recompensa os que o buscam."},
  {v:"8-19",t:"Abraão: saiu sem saber para onde ia, viveu em tendas esperando a cidade de Deus e ofereceu Isaque crendo que Deus podia ressuscitá-lo."},
  {v:"13-16",t:"Todos morreram sem receber as promessas, saudando-as de longe como estrangeiros e peregrinos. Por isso Deus “não se envergonha de ser chamado Deus deles”."},
  {v:"24-26",t:"Moisés preferiu ser maltratado com o povo de Deus a gozar o pecado: considerou “o opróbrio de Cristo” maior riqueza que os tesouros do Egito."},
  {v:"31",t:"Raabe, prostituta e cananeia, está na lista. A fé, não o currículo, é o critério."},
  {v:"35-38",t:"Uns foram libertos, outros torturados sem aceitar libertação. A fé não garante final feliz nesta vida."},
  {v:"39-40",t:"Eles não alcançaram a promessa “para que, sem nós, não fossem aperfeiçoados”: o povo de Deus de todas as épocas será completado junto."}
 ],
 palavras:["pistis","elpis","hypomone","teleios"],
 teologos:[["Calvino","A fé tem os olhos voltados para a palavra e a promessa; por isso é certa mesmo sem ver."],["Agostinho","Fé é crer no que não vês; sua recompensa é ver o que creste (Sermões)."],["William Lane","Mostra o capítulo como parte de um sermão para gerar perseverança, culminando em 12:1-2."],["F. F. Bruce","Destaca a continuidade entre o povo de Deus do AT e da Igreja."]],
 cristo:"Hb 12:2 completa o capítulo: “olhando para Jesus, autor e consumador da fé”, que suportou a cruz pela alegria que lhe estava proposta.",
 perguntas:["Qual herói da lista mais encoraja você e por quê?","Como viver como “estrangeiro e peregrino” hoje?","O que os vv. 35-38 ensinam sobre fé e sofrimento?"]},
{id:"novacriacao",titulo:"Novo céu e nova terra",b:65,c:21,v:[1,8],ref:"Apocalipse 21:1-8",cat:"Novo Testamento",
 tema:"Deus renova toda a criação e habita com seu povo; não haverá mais morte, choro nem dor.",
 contexto:"Depois do juízo da Babilônia, da besta e do diabo, a visão final mostra o destino da história: não a fuga para o céu, mas o céu descendo à terra.",
 notas:[
  {v:"1",t:"Novo (kainos, novo em qualidade) céu e nova terra: cumprimento de Is 65:17. “O mar já não existe”: no imaginário antigo, o mar era símbolo do caos e de onde surgiu a besta (13:1)."},
  {v:"2",t:"A nova Jerusalém “desce do céu” como noiva adornada: a cidade é o povo de Deus."},
  {v:"3",t:"“O tabernáculo (skēnē) de Deus está com os homens”: o propósito do Éden, do tabernáculo e do templo se cumpre. “Eles serão seu povo”: fórmula da aliança (Lv 26:12; Jr 31:33)."},
  {v:"4",t:"Deus enxugará toda lágrima (Is 25:8). Morte, luto, choro e dor pertencem às “primeiras coisas” que passaram."},
  {v:"5",t:"“Eis que faço novas todas as coisas”: não “todas as coisas novas”, mas as mesmas coisas renovadas. Continuidade e transformação."},
  {v:"6",t:"“Está feito” (gegonan). Alfa e Ômega, primeira e última letra do alfabeto grego. Água da vida “de graça”: ecoa Is 55:1."},
  {v:"8",t:"Advertência: os que persistem no mal ficam de fora. A promessa vem com chamado à fidelidade."}
 ],
 palavras:["kainos","skenoo","apokalypsis","zoe","berit"],
 teologos:[["Ireneu","Defendeu que a própria criação será restaurada, não abandonada, porque Deus não desiste da obra das suas mãos."],["Agostinho","Termina “A Cidade de Deus” com o sábado eterno: “ali descansaremos e veremos, veremos e amaremos, amaremos e louvaremos” (XXII.30)."],["N. T. Wright","“Surpreendido pela Esperança”: o objetivo não é ir para o céu, mas o céu e a terra unidos."],["Richard Bauckham","A nova Jerusalém é ao mesmo tempo cidade, noiva e templo: a comunhão plena com Deus."]],
 cristo:"O Cordeiro é a lâmpada da cidade (21:23). O que começou com a ressurreição de Cristo, primícias da nova criação, chega à plenitude.",
 perguntas:["Que lágrima você espera que Deus enxugue?","Como a esperança de uma terra renovada muda o modo de tratar a criação hoje?","O que significa “faço novas todas as coisas” para sua história?"]}
];
